        output.push_str(&format!("[{}]
", section));
        let mut entries: Vec<_> = config.entries(&section, None).collect();
        entries.sort_by_key(|&(k, _)| k);
        for (key, value) in entries {
            output.push_str(&format!("{} = {}
", key, value.as_str().unwrap()));
        }
        output.push_str("\n"); // Blank line after each section
    }

    output
